SELECT p.id AS position_id, e.id, e.observed_at, e.price, e.source, e.delivery_status, e.outcome_reason, e.source_received_at, e.created_at FROM paper_position p JOIN market_price_event e ON e.symbol = p.symbol AND e.observed_at BETWEEN (CASE WHEN p.id = 101 THEN p.closed_at - INTERVAL 4 MINUTE ELSE p.closed_at - INTERVAL 90 SECOND END) AND p.closed_at + INTERVAL 5 SECOND WHERE p.id IN (104,101,96,91,82,78) ORDER BY p.id, e.observed_at LIMIT 800